tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets #for $i in $input: ln -s '$i' input${input.index($i)}.dat && #end for
echo 'merge.count( count=#for $i in $input#input${input.index($i)}.dat-#end for#, output=$output )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | sed 's/-,/,/g' | mothur | tee mothur.out.log
